    ).mapValues { it.value.split('|') }
    fun text(language: String, key: String): String = rows[language]?.getOrNull(keys.indexOf(key))
        ?: rows.getValue("en").getOrNull(keys.indexOf(key)) ?: key
    fun complete(): Boolean = Strings.languages.keys.all { language ->
        rows[language]?.size == keys.size && rows.getValue(language).all(String::isNotBlank)
    }
}
